; IRQ handler. With raster_split_enable set and a raster interrupt, it makes the menu screen splits: from line 0 white background and multicolour, from line $b2 hires, from line $ca mix_colour as background. Else (the CIA 1 timer): UDTIM, the pad read, the button state, the menu flash, the cursor colour and SCNKEY, each when its flag is set.
irq_handler
        sei
        lda raster_split_enable         ; raster_split_enable
        beq irq_timer
        lda VICIRQ                      ; the raster interrupt flag
        and #$01
        beq irq_timer
        lda RASTER
        cmp #$ca                        ; line $ca or below: bottom part
        bcc irq_split_mid
        lda mix_colour                  ; background of the bottom part = mix_colour
        sta BGCOL0
        lda #$00
        sta RASTER                      ; next interrupt at line 0
        jmp irq_raster_end
irq_split_mid
        cmp #$b2                        ; line $b2 or below: middle part
        bcc irq_split_top
        lda SCROLX
        and #$0f                        ; multicolour off
        sta SCROLX
        lda #$ca
        sta RASTER                      ; next interrupt at line $ca
        jmp irq_raster_end
irq_split_top
        lda #$01
        sta BGCOL0                      ; top part: white background
        lda SCROLX
        ora #$10                        ; multicolour on
        sta SCROLX
        lda #$b2
        sta RASTER                      ; next interrupt at line $b2
        jmp irq_raster_end
irq_timer
        jsr UDTIM
        jsr read_pad_registers
        lda CIAICR                      ; acknowledge the CIA 1 interrupt
        lda CIAPRB                      ; bits 2 and 3: the pad buttons (port 1 left and right lines, low = down)
        and #$04
        beq irq_button_down
        lda CIAPRB
        and #$08
        bne irq_button_up
irq_button_down
        lda button_held                 ; set button_press_edge only on the first interrupt with the button down
        bne irq_flash_check
        lda #$01
        sta button_press_edge
        sta button_held
        jmp irq_flash_check
irq_button_up
        lda #$00
        sta button_held
irq_flash_check
        lda flash_enable
        beq irq_cursor_check
        jsr irq_flash
irq_cursor_check
        lda cursor_colour_enable
        beq irq_keys_check
        jsr irq_cursor_colour
irq_keys_check
        lda scan_keys_enable
        beq irq_timer_end
; not executed $09ec-$09ee
        jsr SCNKEY
irq_timer_end
        jsr read_pad_registers
        lda CIAICR
        jmp irq_return
; End of a raster interrupt: acknowledges it in $d019. This path does not read $dc0d.
irq_raster_end
        lda #$81
        sta VICIRQ                      ; acknowledge the raster interrupt
irq_return
